/// Spec #1131 (order 3) — `--explain` on the datasource create path.
///
/// Builds the human-readable plan `zfa datasource create <Entity>
/// --explain` prints INSTEAD of generating: which datasource types are in
/// play for the entity (remote/local are generated by this command; mock
/// and sqlite variants are delegated to their own plugins), which entity
/// fields map to which interface methods (the id field is wired into
/// UpdateParams/DeleteParams/ToggleParams; the entity itself flows through
/// get/create/watch), and the interface shape (the signatures the
/// generation would emit).
library;

import 'dart:io';

import 'package:analyzer/dart/analysis/utilities.dart';
import 'package:analyzer/dart/ast/ast.dart';
import 'package:path/path.dart' as p;

import '../../models/generator_config.dart';
import '../../utils/string_utils.dart';

/// The datasource `--explain` plan builder. Stateless; instantiate freely.
class DatasourceExplainer {
  const DatasourceExplainer();

  Future<String> explain({
    required GeneratorConfig config,
    required String projectRoot,
  }) async {
    final entityName = config.repo != null
        ? config.repo!.replaceAll('Repository', '')
        : config.name;
    final snake = StringUtils.camelToSnake(entityName);
    final out = StringBuffer()
      ..writeln('Datasource plan for `$entityName`')
      ..writeln();

    // --- 1. Datasource types ---------------------------------------------
    final outputBase = p.isAbsolute(config.outputDir)
        ? config.outputDir
        : p.join(projectRoot, config.outputDir);
    final dsDir = p.join(outputBase, 'data', 'datasources', snake);
    final remoteExists = File(
      p.join(dsDir, '${snake}_remote_datasource.dart'),
    ).existsSync();
    final localExists = File(
      p.join(dsDir, '${snake}_local_datasource.dart'),
    ).existsSync();

    out
      ..writeln('Datasource types:')
      ..writeln(
        '  - remote  ${remoteExists ? '(exists — --force to overwrite)' : (config.generateRemote ? '(will be generated)' : '(not requested)')} — '
        '${entityName}RemoteDataSource, the API integration',
      )
      ..writeln(
        '  - local   ${localExists ? '(exists — --force to overwrite)' : (config.generateLocal || config.enableCache ? '(will be generated)' : '(not requested)')} — '
        '${entityName}LocalDataSource, the Hive/DB integration',
      )
      ..writeln(
        '  - mock    (separate plugin — `zfa mock create $entityName`) — the '
        'offline/mock datasource for tests',
      )
      ..writeln(
        '  - sqlite  (separate plugin — `zfa sqlite create $entityName`) — the '
        'sqlite adapter datasource',
      )
      ..writeln();

    // --- 2. Entity fields -> methods --------------------------------------
    final entityFile = File(
      p.join(outputBase, 'domain', 'entities', snake, '$snake.dart'),
    );
    final fields = _entityFields(entityFile);
    out.writeln('Entity fields -> methods:');
    if (fields.isEmpty) {
      out
        ..writeln(
          '  (no entity source at ${_rel(entityFile.path, projectRoot)} — '
          'field mapping unavailable; the interface will still be generated)',
        )
        ..writeln();
    } else {
      for (final field in fields) {
        final isId = field.name == config.idField;
        final isQuery = field.name == config.queryField && !isId;
        if (isId) {
          final wired = [
            if (_wired(config, 'update')) 'update',
            if (_wired(config, 'delete')) 'delete',
            if (_wired(config, 'toggle')) 'toggle',
            if (_wired(config, 'get')) 'get',
            if (_wired(config, 'watch')) 'watch',
          ];
          out.writeln(
            '  - ${field.type} ${field.name} — id-field: its type '
            '(${field.type}) is the type argument the interface wires into '
            'UpdateParams/DeleteParams/ToggleParams; it also keys '
            'get/watch lookups (in this methodset: '
            '${wired.isEmpty ? 'none' : wired.join(', ')})',
          );
        } else if (isQuery) {
          out.writeln(
            '  - ${field.type} ${field.name} — query-field: keys '
            'get/watch lookups through QueryParams',
          );
        } else {
          out.writeln(
            '  - ${field.type} ${field.name} — flows through the entity type '
            '($entityName) consumed by the entity-typed methods '
            '(get, create, update, watch)',
          );
        }
      }
      out.writeln();
    }

    // --- 3. Interface shape -----------------------------------------------
    out
      ..writeln('Interface shape: ${entityName}DataSource (abstract)')
      ..writeln('  mixins: Loggable, FailureHandler');
    final methods = _interfaceSignatures(config, entityName);
    if (methods.isEmpty) {
      out.writeln(
        '  (no CRUD methods — pass --methods get,create,update,delete,list,'
        'watch,getList,watchList to wire them)',
      );
    } else {
      for (final signature in methods) {
        out.writeln('  - $signature');
      }
    }
    return out.toString().trimRight();
  }

  bool _wired(GeneratorConfig config, String method) =>
      config.methods.contains(method);

  /// The interface method signatures the generation would emit, mirroring
  /// DataSourceInterfaceBuilder's method table.
  List<String> _interfaceSignatures(GeneratorConfig config, String entityName) {
    final signatures = <String>[];
    final entityCamel = StringUtils.pascalToCamel(entityName);
    final methods = config.methods;

    if (config.generateInit) {
      signatures
        ..add('Stream<bool> get isInitialized')
        ..add('Future<void> initialize(InitializationParams params)')
        ..add('Future<void> dispose()');
    }
    for (final method in methods) {
      switch (method) {
        case 'get':
          signatures.add('Future<$entityName> get(QueryParams<$entityName>)');
        case 'getList':
          signatures.add(
            'Future<List<$entityName>> getList(ListQueryParams<$entityName>)',
          );
        case 'list':
          signatures.add('Future<List<$entityName>> list(NoParams)');
        case 'create':
          signatures.add(
            'Future<$entityName> create($entityName $entityCamel)',
          );
        case 'update':
          signatures.add(
            'Future<${config.name}> update(UpdateParams<${config.idFieldType}, '
            '${config.name}Patch>)',
          );
        case 'toggle':
          signatures.add(
            'Future<${config.name}> toggle(ToggleParams<${config.idFieldType}, '
            'Field<${config.name}, dynamic>>)',
          );
        case 'delete':
          signatures.add(
            'Future<void> delete(DeleteParams<${config.idFieldType}>)',
          );
        case 'watch':
          signatures.add('Stream<$entityName> watch(QueryParams<$entityName>)');
        case 'watchList':
          signatures.add(
            'Stream<List<$entityName>> watchList(ListQueryParams<$entityName>)',
          );
        default:
          break;
      }
    }
    return signatures;
  }

  /// The entity fields (name + declared type) parsed from the entity
  /// source; empty when the file is absent or malformed (explain must
  /// never crash on a broken entity).
  List<({String name, String type})> _entityFields(File entityFile) {
    if (!entityFile.existsSync()) return const [];
    try {
      final result = parseString(
        content: entityFile.readAsStringSync(),
        path: entityFile.path,
        throwIfDiagnostics: false,
      );
      final fields = <({String name, String type})>[];
      for (final decl
          in result.unit.declarations.whereType<ClassDeclaration>()) {
        final body = decl.body;
        if (body is! BlockClassBody) continue;
        for (final member in body.members) {
          if (member is FieldDeclaration) {
            final type = member.fields.type;
            for (final variable in member.fields.variables) {
              fields.add((
                name: variable.name.lexeme,
                type: type == null ? 'dynamic' : type.toString(),
              ));
            }
          }
        }
      }
      return fields;
    } catch (_) {
      return const [];
    }
  }

  static String _rel(String filePath, String projectRoot) {
    final rel = p.isAbsolute(filePath)
        ? p.relative(filePath, from: projectRoot)
        : filePath;
    return p.normalize(rel).replaceAll('\\', '/');
  }
}
